from taf.ul.sc.unix_functionality import UnixFunctionality


class FzpFunctionality(UnixFunctionality):
    def __init__(self,
                 device_name='ENB1',    # type: 'Optional[str]'
                 device=None,           # type: 'Optional[FzmConsole]'
                 autoconnect=False,     # type: 'Optional[bool]'
                 get_device=False       # type: 'Optional[bool]'
                 ):

        super(FzpFunctionality, self).__init__(device_name=device_name, device=device,
                                               autoconnect=autoconnect, get_device=get_device)
